-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 35 recettes, 7 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', 'Wikimedia Commons', ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · Wikimedia Commons',
        true, true, 'Photo Wikimedia Commons vérifiée : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"bajan-fish-cakes","country":"BB","original":"Bajan fish cakes","title":"Fish cakes de la Barbade (beignets de morue salée aux herbes)","en":"Bajan fish cakes (salt cod fritters)","es":"Fish cakes de Barbados (buñuelos de bacalao salado)","desc":"Beignets croustillants de morue salée aux herbes, piment scotch bonnet et oignon vert, servis avec une sauce piquante — en-cas national de la Barbade.","cat":"Cuisine de rue","diff":"easy","prep":30,"cook":20,"serv":6,"ing":[["Morue salée",250,"g","dessalée et émiettée"],["Farine",250,"g",null],["Levure chimique",1,"c. à thé",null],["Oignons verts",3,null,"hachés"],["Thym et persil",1,"poignée","hachés"],["Piment scotch bonnet",0.5,null,"haché"],["Eau",250,"ml",null],["Huile",750,"ml","pour la friture"],["Sel",0.5,"c. à thé",null]],"steps":["Mélanger farine, levure et sel.","Ajouter morue, oignons verts, herbes et piment.","Verser l’eau pour obtenir une pâte épaisse qui tombe de la cuillère.","Frire des cuillerées de pâte 3 à 4 minutes jusqu’à ce qu’elles soient dorées.","Servir avec une sauce pimentée (Bajan pepper sauce)."],"photo":null},{"slug":"pudding-and-souse","country":"BB","original":"Pudding and souse","title":"Pudding and souse (porc mariné au citron et boudin de patate douce)","en":"Bajan pudding and souse","es":"Pudding and souse (cerdo marinado al limón y morcilla de boniato)","desc":"Plat du samedi à la Barbade : porc poché mariné au citron vert, concombre et piment, servi avec un boudin de patate douce épicé.","cat":"Plat principal","diff":"medium","prep":40,"cook":90,"serv":6,"ing":[["Épaule ou jarret de porc",1,"kg",null],["Citrons verts",6,null,"jus"],["Concombre",1,null,"en fines rondelles"],["Oignon",1,null,"en fines lamelles"],["Piment scotch bonnet",1,null,"haché"],["Patates douces",1,"kg","râpées"],["Thym et oignon vert",1,"poignée",null],["Clous de girofle moulus",0.5,"c. à thé",null],["Beurre",40,"g",null],["Sel",2,"c. à thé",null]],"steps":["Pocher le porc 1 heure dans l’eau salée, le refroidir et le trancher finement.","Mélanger jus de citron, concombre, oignon, piment, sel et un peu d’eau; y faire mariner le porc au moins 2 heures.","Mélanger les patates douces râpées avec les herbes, le girofle, le beurre et le sel.","Cuire ce mélange dans un plat couvert au four 1 heure à 170 °C (version sans boyau).","Servir le souse froid avec le pudding tranché."],"photo":null},{"slug":"conkies-barbade","country":"BB","original":"Conkies","title":"Conkies de la Barbade (maïs, coco et patate douce en feuille de bananier)","en":"Bajan conkies (cornmeal and coconut steamed in banana leaves)","es":"Conkies de Barbados (maíz, coco y boniato en hoja de plátano)","desc":"Pâte sucrée de maïs, noix de coco, citrouille et patate douce aux épices, cuite à la vapeur en feuille de bananier pour l’Independence Day.","cat":"Dessert","diff":"medium","prep":40,"cook":60,"serv":12,"ing":[["Semoule de maïs",250,"g",null],["Noix de coco râpée",200,"g",null],["Potiron râpé",200,"g",null],["Patate douce râpée",200,"g",null],["Sucre roux",200,"g",null],["Raisins secs",80,"g",null],["Beurre fondu",100,"g",null],["Lait",250,"ml",null],["Muscade, cannelle et vanille",2,"c. à thé",null],["Feuilles de bananier",12,null,"ramollies"]],"steps":["Mélanger tous les ingrédients secs et râpés.","Ajouter beurre, lait et épices pour une pâte épaisse.","Déposer 3 cuillerées sur chaque feuille et plier en paquet.","Cuire 1 heure à la vapeur.","Servir tiède."],"photo":null},{"slug":"guava-duff","country":"BS","original":"Guava duff","title":"Guava duff des Bahamas (roulé à la goyave, sauce au rhum)","en":"Bahamian guava duff (guava roll with rum sauce)","es":"Guava duff de Bahamas (rollo de guayaba con salsa de ron)","desc":"Pâte roulée autour d’une purée de goyave, cuite à la vapeur et nappée d’une sauce au beurre et au rhum, dessert national des Bahamas.","cat":"Dessert","diff":"medium","prep":40,"cook":90,"serv":8,"ing":[["Farine",350,"g",null],["Beurre",100,"g",null],["Sucre",60,"g",null],["Levure chimique",2,"c. à thé",null],["Lait",150,"ml",null],["Pulpe de goyave",400,"g",null],["Cannelle et muscade",1,"c. à thé",null],["Beurre (sauce)",100,"g",null],["Sucre glace (sauce)",150,"g",null],["Rhum",4,"c. à soupe",null]],"steps":["Sabler farine, beurre, sucre et levure; ajouter le lait pour une pâte souple.","Étaler en rectangle, tartiner de goyave épicée et rouler.","Envelopper serré dans un linge fariné ou de l’aluminium.","Cuire 1 h 30 à la vapeur ou au bain-marie.","Battre beurre et sucre glace avec le rhum et servir en sauce sur les tranches."],"photo":null},{"slug":"johnnycake-bahamas","country":"BS","original":"Johnnycake","title":"Johnnycake des Bahamas (pain de poêle au beurre)","en":"Bahamian johnnycake","es":"Johnnycake de Bahamas (pan dulce de sartén)","desc":"Pain moelleux et légèrement sucré, cuit au four ou à la poêle, accompagnement des soupes et du souse aux Bahamas.","cat":"Pain","diff":"easy","prep":15,"cook":35,"serv":8,"ing":[["Farine",500,"g",null],["Levure chimique",4,"c. à thé",null],["Sucre",80,"g",null],["Beurre",120,"g",null],["Lait",300,"ml",null],["Sel",1,"c. à thé",null]],"steps":["Mélanger farine, levure, sucre et sel.","Sabler avec le beurre.","Ajouter le lait et former une pâte souple sans trop pétrir.","Étaler dans un moule beurré sur 3 cm.","Cuire 30 à 35 minutes à 190 °C et servir tiède."],"photo":null},{"slug":"chicken-souse-bahamas","country":"BS","original":"Chicken souse","title":"Chicken souse des Bahamas (soupe de poulet au citron vert)","en":"Bahamian chicken souse (lime and chicken soup)","es":"Chicken souse de Bahamas (sopa de pollo con lima)","desc":"Bouillon clair de poulet, pommes de terre et oignon, très acidulé au citron vert et relevé de piment, servi le samedi matin.","cat":"Soupe","diff":"easy","prep":15,"cook":45,"serv":4,"ing":[["Poulet",1.2,"kg","en morceaux"],["Pommes de terre",3,null,"en cubes"],["Oignon",1,null,"émincé"],["Céleri",2,"branches",null],["Citron